BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH members AS MATERIALIZED(SELECT DISTINCT m.con_code AS ts_code FROM core_serving.dc_member m JOIN core_serving.dc_index i ON i.trade_date=m.trade_date AND i.ts_code=m.ts_code WHERE m.trade_date=DATE '2026-09-30' AND i.idx_type='行业板块' AND i.level='东财一级行业'),
base AS MATERIALIZED(SELECT m.ts_code FROM members m JOIN raw_tushare.stock_basic s ON s.ts_code=m.ts_code WHERE s.ts_code !~ '^(200|900)' AND s.list_date<=DATE '2026-09-30' AND (s.delist_date IS NULL OR s.delist_date>DATE '2026-09-30')),i AS MATERIALIZED(SELECT ts_code,end_date,(CASE WHEN comp_type='1' THEN revenue ELSE total_revenue END) IS NOT NULL r_ok,n_income_attr_p IS NOT NULL p_ok FROM core_serving.equity_income WHERE end_date IN(DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31')),c AS MATERIALIZED(SELECT ts_code,end_date,n_cashflow_act IS NOT NULL c_ok FROM core_serving.equity_cashflow WHERE end_date IN(DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31')),f AS MATERIALIZED(SELECT DISTINCT ON(ts_code,end_date) ts_code,end_date,profit_dedt,q_dtprofit FROM raw_tushare.fina_indicator WHERE end_date IN(DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31') ORDER BY ts_code,end_date,CASE update_flag WHEN '1' THEN 0 ELSE 1 END,ann_date DESC,fetched_at DESC,source_content_hash DESC),q AS(SELECT a.ts_code,count(*) FILTER(WHERE i.r_ok) r_periods,count(*) FILTER(WHERE i.p_ok) p_periods,count(*) FILTER(WHERE c.c_ok) c_periods FROM base a CROSS JOIN(VALUES(DATE '2024-09-30'),(DATE '2024-12-31'),(DATE '2025-09-30'),(DATE '2025-12-31')) d(end_date) LEFT JOIN i ON i.ts_code=a.ts_code AND i.end_date=d.end_date LEFT JOIN c ON c.ts_code=a.ts_code AND c.end_date=d.end_date GROUP BY a.ts_code),dh AS(SELECT a.ts_code,count(*) FILTER(WHERE f.q_dtprofit IS NOT NULL) annual_direct_q4_years FROM base a LEFT JOIN f ON f.ts_code=a.ts_code AND f.end_date IN(DATE '2024-12-31',DATE '2025-12-31') GROUP BY a.ts_code)
SELECT jsonb_build_object('section','strict_2024_2025_q4_inputs','as_of',current_timestamp,'reference_cohort','2026-09-30 industry members filtered by stock_basic A-share eligibility; not final classification decision','cohort_codes',(SELECT count(*) FROM base),'both_years_revenue',(SELECT count(*) FROM q WHERE r_periods=4),'both_years_parent_profit',(SELECT count(*) FROM q WHERE p_periods=4),'both_years_ocf',(SELECT count(*) FROM q WHERE c_periods=4),'both_years_all_three',(SELECT count(*) FROM q WHERE r_periods=4 AND p_periods=4 AND c_periods=4),'both_years_direct_q4_deducted',(SELECT count(*) FROM dh WHERE annual_direct_q4_years=2));
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s';
WITH q AS(SELECT trade_date,count(*) codes,count(*) FILTER(WHERE close>0 AND total_mv>0 AND total_share>0) basic_valid,count(pe_ttm) pe_nonnull,count(pb) pb_nonnull,count(dv_ttm) dividend_nonnull FROM core_serving.equity_daily_basic WHERE trade_date IN(DATE '2024-10-31',DATE '2024-12-31',DATE '2025-10-31',DATE '2025-12-31',DATE '2026-10-30') GROUP BY trade_date)
SELECT jsonb_build_object('section','valuation_2024_scope_refresh','as_of',current_timestamp,'data',jsonb_agg(to_jsonb(q) ORDER BY trade_date)) FROM q;
COMMIT;
